parameters.text:
=You are an expert job-search planning assistant.

Your task is to analyze the candidate's profile and create targeted web search queries for finding CURRENT job openings.

Candidate Name:
{{ $('On form submission').first().json['Your Name'] }}

Skills:
{{ $('On form submission').first().json['Your Skills'] }}

Preferred Location:
{{ $('On form submission').first().json['Preferred Location'] || 'Any' }}

Experience Level:
{{ $('On form submission').first().json['Experience Level'] || 'Any' }}

Work Preference:
{{ $('On form submission').first().json['Work Preference'] || 'Any' }}

Create 3 to 5 suitable job roles based on the candidate's skills and experience.

For each job role, create ONE highly specific web search query.

The search query must include:
- Job role
- Experience level
- Preferred location
- Work preference when relevant
- Current/recent job openings

IMPORTANT:
- Do NOT invent company names.
- Do NOT invent job openings.
- Do NOT provide fake URLs.
- These queries will be sent to a web search API to find real job listings.
- Prefer queries that return pages containing job title, company name, location and application information.

Return ONLY valid JSON in this exact structure:

{
  "candidate": {
    "name": "...",
    "skills": "...",
    "preferred_location": "...",
    "experience_level": "...",
    "work_preference": "..."
  },
  "job_searches": [
    {
      "job_role": "...",
      "search_query": "..."
    },
    {
      "job_role": "...",
      "search_query": "..."
    },
    {
      "job_role": "...",
      "search_query": "..."
    }
  ]
}

parameters.jsonSchemaExample:
{
  "candidate": {
    "name": "sakib",
    "skills": "AI,Laravel,Java",
    "preferred_location": "Dhaka",
    "experience_level": "Junior",
    "work_preference": "Remote"
  },
  "job_searches": [
    {
      "job_role": "Junior AI Developer",
      "search_query": "Junior AI Developer remote job in Dhaka current openings"
    },
    {
      "job_role": "Junior Laravel Developer",
      "search_query": "Junior Laravel Developer remote job in Dhaka current openings"
    },
    {
      "job_role": "Junior Java Developer",
      "search_query": "Junior Java Developer remote job in Dhaka current openings"
    }
  ]
}

parameters.jsCode:
const output = $input.first().json.output;

const jobSearches = output?.job_searches || [];

return jobSearches.map(job => ({
  json: {
    jobRole: job.job_role,
    searchQuery: job.search_query,
    candidateName: output?.candidate?.name || '',
    skills: output?.candidate?.skills || '',
    preferredLocation: output?.candidate?.preferred_location || '',
    experienceLevel: output?.candidate?.experience_level || '',
    workPreference: output?.candidate?.work_preference || ''
  }
}));

const results = [];

for (const item of $input.all()) {
  const organic = item.json.organic || [];

  for (const job of organic) {
    results.push({
      json: {
        title: job.title || '',
        link: job.link || '',
        snippet: job.snippet || '',
        position: job.position || null,
      }
    });
  }
}

return results;

const candidate = $('On form submission').first().json;

return $input.all().map(item => ({
  json: {
    ...item.json,
    candidateName: candidate['Your Name'] || '',
    skills: candidate['Your Skills'] || '',
    preferredLocation: candidate['Preferred Location'] || '',
    experienceLevel: candidate['Experience Level'] || '',
    workPreference: candidate['Work Preference'] || ''
  }
}));

const items = $input.all();

const jobs = items.map(item => ({
  title: item.json.title || '',
  link: item.json.link || '',
  snippet: item.json.snippet || '',
  position: item.json.position || null
}));

const first = items[0]?.json || {};

return [{json:{candidate:{name:first.candidateName||'',skills:first.skills||'',preferredLocation:first.preferredLocation||'',experienceLevel:first.experienceLevel||'',workPreference:first.workPreference||''},jobs}}];

parameters.text:
=You are a job recommendation assistant.

Analyze the candidate profile and the available job listings.

Candidate:
Name: {{ $json.candidate.name }}
Skills: {{ $json.candidate.skills }}
Preferred Location: {{ $json.candidate.preferredLocation }}
Experience Level: {{ $json.candidate.experienceLevel }}
Work Preference: {{ $json.candidate.workPreference }}

Job Listings:
{{ JSON.stringify($json.jobs) }}

Rank the jobs from best to worst match.

For each recommended job:
- Give a match score from 0 to 100.
- Explain why it matches the candidate.
- Mention any important mismatch or concern.
- Only use information present in the provided data.
- Do not invent salary, requirements, company information, or other details.

Return the top 5 best matching jobs.

parameters.jsonSchemaExample:
{
  "recommendations": [
    {
      "jobTitle": "Remote AI Engineer Jobs in Bangladesh",
      "company": "Crossover",
      "location": "Remote",
      "matchScore": 85,
      "reason": "Matches the candidate's AI and Java skills and remote work preference.",
      "link": "https://www.crossover.com/jobs/ai-engineer/bd"
    }
  ],
  "summary": "These jobs are suitable for the candidate based on skills, location, experience, and work preference."
}

parameters.jsCode:
const recommendations = $json.output?.recommendations || $json.recommendations || [];

let email = `<h2>Your Personalized Job Recommendations</h2>
<p>Here are the jobs that best match your profile:</p>`;

recommendations.forEach((job,index)=>{email += `<hr><h3>${index+1}. ${job.jobTitle||'Job Opportunity'}</h3><p><strong>Company:</strong> ${job.company||'N/A'}<br><strong>Location:</strong> ${job.location||'N/A'}<br><strong>Match Score:</strong> ${job.matchScore||0}%</p><p><strong>Why it matches:</strong><br>${job.reason||'No reason provided.'}</p>${job.link?`<p><a href=

>Apply / View Job</a></p>`:''}`;});

email += `<hr><p>Good luck with your job search!</p>`;
return [{json:{subject:'Your Personalized Job Recommendations',emailBody:email}}];
